class Instruction(
    metaclass=_InstructionMeta,
    sort_function=None,
    ftype="GENERIC",
    required=None,
    defaults=None,
):
    """Instruction class description"""

    @classmethod
    def _params_include_defaults(cls, params):
        """check the parameters of the call"""
        params_wdef = {}
        for default_key, default_val in cls.defaults.items():
            params_wdef[default_key] = params.get(default_key, default_val)
        for param_key, param_val in params.items():
            params_wdef[param_key] = param_val
        for required_key in cls.required:
            if required_key not in params_wdef:
                raise ValueError(
                    f"A value for '{required_key}' is required in Instruction {cls.itype}"
                )
        return params_wdef

    def __init__(self, **params):
        params = self._params_include_defaults(params)
        self._params = dict(params)
        self._sort_key = self._get_sort_key()
        self._protected = True
        self._itype = self.__class__.ftype

    def _get_sort_key(self, function=None):
        """get a sort key from the instruction"""
        if function is None:
            function = self.__class__.sort_func
        return function(self)

    @property
    def sort_key(self):
        """access protected sort key attribute"""
        return self._sort_key

    @sort_key.setter
    def sort_key(self, new_sort_key):
        if not isinstance(new_sort_key, tuple):
            new_sort_key = tuple([new_sort_key])
        self._sort_key = tuple(
            str(sort_key_entry) for sort_key_entry in new_sort_key
        )

    def update_sort_key(self, function=None):
        """recall the sort key function"""
        self._sort_key = self._get_sort_key(function)

    def __getitem__(self, key):
        return self._params[key]

    def __setitem__(self, key, value):
        if self._protected:
            raise ValueError("Instruction is protected and cannot be modified")
        self._params[key] = value

    def lookup(self, use_dict=False, **requests):
        """lookup parameters in the Instruction. Use default in request if not set.
        Return tuple or dict"""
        if use_dict:
            return {
                key: (self._params[key] if key in self._params else default)
                for key, default in requests.items()
            }
        return tuple(
            self._params[key] if key in self._params else default
            for key, default in requests.items()
        )

    def __enter__(self):
        self._protected = False

    def __exit__(self, exc_type, exc_val, exc_tb):
        self._protected = True

    def set(self, **requests):
        """set parameters in the Instruction. Use defaults if not set.
        Return tuple or dict"""
        if self._protected:
            if __debug__:
                raise ValueError(
                    "Instruction is protected and cannot be modified"
                )
            return False
        for rkey, rval in requests.items():
            self._params[rkey] = rval
        return True

    def get(self, *keys, use_dict=False, defaults=None):
        """lookup parameters in the Instruction. Use defaults if not set.
        Return tuple or dict"""
        if defaults is None:
            defaults = {}
        if use_dict:
            return {
                key: self._params.get(key, defaults.get(key, None))
                for key in keys
            }
        return tuple(
            self._params.get(key, defaults.get(key, None)) for key in keys
        )

    def __gt__(self, other):
        return self.sort_key > other.sort_key

    def __lt__(self, other):
        return self.sort_key < other.sort_key

    def __eq__(self, other):
        return self.sort_key == other.sort_key

    def __str__(self):
        return f"<Instruction '{self.itype}' [{', '.join([f'{key}={value}' for key, value in self._params.items()])}]>"

    def __repr__(self):
        return f"<I:{'|'.join(map(str, self._params.values()))}>"

    def __len__(self):
        return 1

    @property
    def num_instructions(self):
        return 1

    @property
    def itype(self):
        """access object level property for ftype attribute"""
        return str(self._itype)

    @property
    def ftype(self):
        """access class level property for ftype attribute"""
        return str(self.__class__.ftype)

    @property
    def required(self):
        """access class level property for required attribute"""
        return list(self.__class__.required)

    @property
    def defaults(self):
        """access class level property for defaults attribute"""
        return dict(self.__class__.defaults)

    @property
    def sort_func(self):
        """access class level property for defaults attribute"""
        return self.__class__.sort_func

    def is_compatible(self, other):
        """check if the instruction fits into a group"""
        return self.itype == other.itype

    def unpack(self, depth=None):
        """unpack the instructions inside"""
        if depth is None or depth > 0:
            yield self

    @classmethod
    def combine(cls, *instructions, ident=None):
        itype = instructions[0].itype
        assert all(
            itype == instr.itype for instr in instructions
        ), "All instructions must be of the same type"
        if ident is None:
            group_names = []
            num_instr = 0
            for instr in instructions:
                if isinstance(instr, InstructionGroup):
                    group_names.append(instr.ident)
                else:
                    num_instr += 1
            ident = "+".join(
                (
                    "*" + str(instr.ident)
                    for instr in instructions
                    if isinstance(instr, InstructionGroup)
                )
            )
            if num_instr > 0:
                ident += " + " if group_names else ""
                ident += f"C[{num_instr} instructions]"
        return InstructionGroup(
            instructions=sum(
                (
                    list(instr.instructions)
                    if isinstance(instr, InstructionGroup)
                    else [instr]
                    for instr in instructions
                ),
                start=[],
            ),
            itype=itype,
            ident=ident,
        )

    def __add__(self, other):
        assert isinstance(
            other, Instruction
        ), "Only Instruction instances can be combined"
        return Instruction.combine(self, other)


